function assistantStructuredView(){const s=assistantState,r=s.swapDraft||allRecipes().find(v=>v.id===s.contextIds[0]);if(!r||s.task!=='ask')return '';return `<section class="ai-recipe-sections"><details><summary><img src="media/experience_ingredients.png" alt="">${s.swapDraft?'本次替换草稿':'菜谱步骤'} ↓</summary>${s.swapDraft?`<p>${esc(s.swapDraft.methodNotes)}</p>`:''}${AssistantExperience.experienceSections(r).map(section=>`<details data-experience-section="${section.key}" ${assistantExpanded.has(section.key)?'open':''}><summary>${esc(section.title)}</summary>${section.lines.map(line=>`<p>${esc(line)}</p>`).join('')}</details>`).join('')}<div class="row">${!s.swapDraft?btn('进入做菜','assistantCook',r.id):''}<button data-action="go" data-value="timers"><img class="ai-icon-art" src="media/experience_timer.png" alt="">计时器</button></div></details>${!s.swapDraft&&AssistantExperience.experienceSwaps(r).length?`<details><summary>食材替换对照 ↓</summary>${AssistantExperience.experienceSwaps(r).map((swap,i)=>`<article class="ai-swap"><strong>${esc(swap.from)} → ${esc(swap.to)}</strong><p>参考起点 ${swap.ratio===1?'同单位约1:1':swap.ratio+'倍'} · ${esc(swap.texture)}</p><p>${esc(swap.operation)}</p><small>${esc(swap.caution)}</small>${btn('形成这次草稿','assistantSwap',i)}</article>`).join('')}</details>`:''}</section>`;}
