function previewAssistantAdjustment(kind){try{const s=assistantState;if(s.busy)return;const candidates=parity.drawFilter?F.filterRecipes(allRecipes(),parity.drawFilter,store.state.foods,M.dateString(new Date())):allRecipes();const options=AssistantExperience.experienceAdjustmentOptions(candidates,s.contextIds,s.menuOptions,kind);const result=AssistantExperience.experienceAdjustMenu(candidates,s.contextIds,s.menuOptions,kind);s.menuPreview={result,options};render();}catch(e){toast(e.message);}}
function applyAssistantAdjustment(){const s=assistantState;if(!s.menuPreview)return;const before=s.contextIds.slice(),beforeOptions=clone(s.menuOptions),after=s.menuPreview.result.ids.slice();s.contextIds=after;s.menuOptions=s.menuPreview.options;s.menuPreview=null;s.followup=false;s.prompt='按调整后的菜品安排备菜与制作顺序。';render();polishOfferUndo('餐单草案已调整',async()=>{if(JSON.stringify(s.contextIds)!==JSON.stringify(after))throw Error('餐单已变化');s.contextIds=before;s.menuOptions=beforeOptions;});}
function updateAssistantStream(){const s=assistantState,pane=document.querySelector('.ai-chat-scroll'),follow=!pane||pane.scrollHeight-pane.scrollTop-pane.clientHeight<80;let text=document.querySelector('.ai-stream-text');if(!text){const thinking=document.querySelector('.ai-thinking');if(thinking){text=document.createElement('p');text.className='ai-stream-text';thinking.insertBefore(text,thinking.querySelector('.ai-typing'));}}if(text)text.textContent=s.streamText;if(follow&&pane)pane.scrollTop=pane.scrollHeight;}
