const experienceUndoActions=actions;actions=async function(action,value){if(action!=='confirmProcurement')return experienceUndoActions(action,value);const before=new Set(store.state.shopping.map(s=>s.id)),owner=parity.epoch;const result=await experienceUndoActions(action,value);const ids=store.state.shopping.filter(s=>!before.has(s.id)).map(s=>s.id),expected=JSON.stringify(store.state.shopping);if(ids.length)polishOfferUndo('已加入采购',async()=>{if(owner!==parity.epoch)throw Error('账号已变化');await store.undoAddedRows('shopping_list',ids,expected);});return result;};
const experiencePlanSubmit=submit;submit=async function(action){if(action!=='plan')return experiencePlanSubmit(action);const before=new Set(store.state.plans.map(p=>p.id)),owner=parity.epoch;const result=await experiencePlanSubmit(action);const ids=store.state.plans.filter(p=>!before.has(p.id)).map(p=>p.id),expected=JSON.stringify(store.state.plans);if(ids.length)polishOfferUndo('已加入计划',async()=>{if(owner!==parity.epoch)throw Error('账号已变化');await store.undoAddedRows('meal_plans',ids,expected);});return result;};
// Route effects belong to androidMotion. Transforming #screen here would
// duplicate transitions and turn its fixed action bars into moving descendants.
let assistantCoverTransition=null,assistantCoverGhost=null,assistantCoverAnimation=null,assistantCoverTarget=null;
function clearAssistantCover(){
 assistantCoverAnimation?.cancel();assistantCoverAnimation=null;
 assistantCoverGhost?.remove();assistantCoverGhost=null;
 assistantCoverTarget?.style.removeProperty('opacity');assistantCoverTarget=null;
}
function assistantCoverReduced(){return matchMedia('(prefers-reduced-motion: reduce)').matches||document.body.classList.contains('reduced-motion');}
document.addEventListener('click',event=>{
 const image=event.target.closest('.ai-recipe-open')?.querySelector('img');
 if(image&&!assistantCoverReduced())assistantCoverTransition={src:image.src,rect:image.getBoundingClientRect()};
},true);
const experienceMotionRender=render;
render=function(){
 clearAssistantCover();experienceMotionRender();
 const from=assistantCoverTransition;assistantCoverTransition=null;
 if(page!=='recipe'||!from||assistantCoverReduced())return;
 const target=document.querySelector('.recipe-detail-summary img');if(!target)return;
 const to=target.getBoundingClientRect(),ghost=document.createElement('img');ghost.src=from.src;ghost.className='ai-cover-ghost';
 Object.assign(ghost.style,{left:from.rect.x+'px',top:from.rect.y+'px',width:from.rect.width+'px',height:from.rect.height+'px'});
 document.body.append(ghost);assistantCoverGhost=ghost;assistantCoverTarget=target;target.style.opacity='0';
 try{assistantCoverAnimation=ghost.animate([{left:from.rect.x+'px',top:from.rect.y+'px',width:from.rect.width+'px',height:from.rect.height+'px'},{left:to.x+'px',top:to.y+'px',width:to.width+'px',height:to.height+'px'}],{duration:240,easing:'cubic-bezier(.2,.8,.2,1)',fill:'forwards'});assistantCoverAnimation.onfinish=clearAssistantCover;}catch{clearAssistantCover();}
};
const experienceVisibility=window.platformVisibility;window.platformVisibility=function(visible){if(!visible){clearAssistantCover();assistantCoverTransition=null;if(assistantState.busy){pauseAssistant();assistantState.streamText='';}}return experienceVisibility(visible);};
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',()=>{if(assistantCoverReduced())clearAssistantCover();});
new MutationObserver(()=>{if(assistantCoverReduced())clearAssistantCover();}).observe(document.body,{attributes:true,attributeFilter:['class']});

let assistantSheetFocus=null;
const assistantSheetRender=render;render=function(){const wasOpen=!!document.querySelector('.ai-launcher');if(!wasOpen&&assistantState.launcher){const el=document.activeElement;assistantSheetFocus=el?.dataset?.action?{action:el.dataset.action,value:el.dataset.value||''}:null;}assistantSheetRender();const sheet=document.querySelector('.ai-launcher');if(sheet&&!wasOpen){sheet.querySelector('button')?.focus({preventScroll:true});}else if(wasOpen&&!sheet&&assistantSheetFocus){const key=assistantSheetFocus;[...document.querySelectorAll('[data-action]')].find(e=>e.dataset.action===key.action&&(e.dataset.value||'')===key.value)?.focus({preventScroll:true});assistantSheetFocus=null;}};
document.addEventListener('keydown',e=>{const sheet=document.querySelector('.ai-launcher');if(!sheet)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();assistantState.launcher=false;render();return;}if(e.key==='Tab'){const buttons=[...sheet.querySelectorAll('button:not(:disabled),[tabindex="0"]')];const first=buttons[0],last=buttons[buttons.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}},true);
const assistantSheetBack=handleBack;handleBack=function(){if(assistantState.launcher){assistantState.launcher=false;render();return;}return assistantSheetBack();};

document.addEventListener('toggle',e=>{if(e.target.matches?.('.ai-clarify'))assistantState.choiceOpen=e.target.open;},true);

function assistantNativeView(){const s=assistantState,d=s.nativeDraft;if(!d)return '';return `<section class="ai-native-card">${d.choices.map(id=>{const f=store.state.foods.find(f=>f.id===id);return f?btn(f.name+' · '+f.quantity+f.unit+' · '+f.location+' · '+(f.purchasedAt||'购入日期未记'),'assistantNativeBatch',id):''}).join('')}${d.ready?`<button class="ai-native-confirm" data-action="assistantNativeApply" ${s.nativeApplied||s.applying?'disabled':''}>${s.nativeApplied?'已完成':d.kind==='consume'?'确认扣减':'确认保存为私房菜'}</button>`:''}</section>`;}
async function applyAssistantNative(){const s=assistantState,d=s.nativeDraft;if(!d?.ready||s.nativeApplied||s.applying||s.owner!==cloud.session.userId)return;const owner=cloud.session.userId,seq=s.seq;s.applying=true;render();try{
 if(!confirm(d.message+'\n确认执行？'))return;
 if(owner!==cloud.session.userId||seq!==s.seq||d!==s.nativeDraft)throw Error('账号或操作已变化');
 if(d.kind==='consume'){
  const f=store.state.foods.find(f=>f.id===d.targetId);if(!f||JSON.stringify(f)!==d.expected)throw Error('库存已变化，请重新提出扣减');await store.consume(f,d.quantity);const undo=await store.lastUndo();polishOfferUndo('已扣减'+d.quantity+d.unit,async()=>{if(owner!==cloud.session.userId||!undo||(await store.lastUndo())?.id!==undo.id)throw Error('账号或最近操作已变化');await store.undoLast();});
 }else{
  const source=allRecipes().find(r=>r.id===d.targetId);if(!source||JSON.stringify(source)!==d.expected)throw Error('菜谱已变化，请重新选择');const r=AssistantNative.assistantPrivateRecipe(source);await store.saveAssistantRecipe(r,s.nativeBase);const expected=JSON.stringify(store.state.recipes.find(v=>v.id===r.id));polishOfferUndo('已保存为私房菜',async()=>{if(owner!==cloud.session.userId)throw Error('账号已变化');await store.undoAssistantRecipe(r.id,expected);});
 }
 s.nativeApplied=true;s.result.text=d.kind==='consume'?'已扣减'+d.quantity+d.unit+'，库存和消耗流水已更新。':'已保存到你的私房菜，做法和来源一并保留。';toast('操作已完成，可撤销');
 }catch(e){if(owner===cloud.session.userId&&seq===s.seq)s.error=e.message;}finally{s.applying=false;if(assistantVisible())render();}}

